/** Firmware icon looked up by its asset name (symbol without the I_/A_ prefix). */
typedef struct {
    const char* name;
    const Icon* icon;
} AssetIconName;

/** All firmware icons, sorted by name (strcmp order). Generated by gen_icon_names.py. */
extern const AssetIconName assets_icon_names[];
extern const size_t assets_icon_names_count;

